package com.shazwan.idash;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Real category screens, guarded navigation, installed-app validation and explicit reset. Disposable emulator only. */
public class SettingsCompleteChecks extends Instrumentation {
 LauncherActivity a;SharedPreferences prefs;Map<String,?> before;int count;
 void check(boolean ok,String message){if(!ok)throw new AssertionError(message);count++;}
 void ui(Runnable task){Throwable[] error={null};runOnMainSync(()->{try{task.run();}catch(Throwable e){error[0]=e;}});waitForIdleSync();if(error[0]!=null)throw new AssertionError(error[0]);}
 View find(View v,String name){if(name.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View result=find(g.getChildAt(i),name);if(result!=null)return result;}}return null;}
 void open(String key)throws Exception{ui(()->new DashSettings(a).open(key));Thread.sleep(650);waitForIdleSync();}
 void geometry(View view){if(view.isClickable()){Rect visible=new Rect();check(view.getWidth()>=a.dp(48)&&view.getHeight()>=a.dp(48),"touch target >=48dp: "+view.getContentDescription());check(view.getGlobalVisibleRect(visible)&&visible.height()==view.getHeight(),"interactive control not clipped: "+view.getContentDescription());}if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)geometry(group.getChildAt(i));}}
 void capture(String key)throws Exception{Thread.sleep(4000);waitForIdleSync();ui(()->geometry(a.stage));Bitmap bitmap=getUiAutomation().takeScreenshot();check(bitmap!=null,"actual Settings screenshot: "+key);String size=a.getResources().getDisplayMetrics().widthPixels+"x"+a.getResources().getDisplayMetrics().heightPixels;try(OutputStream out=new FileOutputStream(new File(a.getFilesDir(),"settings-"+key+"-"+size+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}
 void ready()throws Exception{long until=SystemClock.elapsedRealtime()+30000;while(!a.appearanceEditor.cacheReady&&SystemClock.elapsedRealtime()<until)Thread.sleep(100);check(a.appearanceEditor.cacheReady,"Appearance ready");Thread.sleep(400);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();int code=Activity.RESULT_CANCELED;try{
  prefs=getTargetContext().getSharedPreferences("idash",0);before=new HashMap<>(prefs.getAll());a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));CountDownLatch loaded=new CountDownLatch(1);a.worker.execute(()->a.main.post(loaded::countDown));check(loaded.await(30,TimeUnit.SECONDS),"installed apps loaded");ui(()->prefs.edit().putInt("dock_size",0).apply());open("");
  ui(()->{for(String key:DashSettings.KEYS){View tile=find(a.stage,"Settings: "+key);Rect r=new Rect();check(tile!=null,"category exists: "+key);check(tile.getWidth()>=a.dp(48)&&tile.getHeight()>=a.dp(48),"category touch target: "+key);check(tile.getGlobalVisibleRect(r)&&r.height()==tile.getHeight(),"category not clipped: "+key);}});capture("home");
  open("Appearance");ready();AppearanceEditor draft=a.appearanceEditor;int originalTint=draft.saved.tint;ui(()->{draft.change(3,(originalTint+1)%5);a.render();check(a.appearanceEditor==draft&&draft.dirty,"same-page refresh keeps draft");new DashSettings(a).open("Home & Dock");check(a.settingsNavigation.prompt!=null&&"Appearance".equals(a.settingsSection),"navigation prompts before losing draft");a.settingsNavigation.prompt.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();check(a.appearanceEditor==draft&&!draft.closed,"Stay retains original editor");});ui(a::onBackPressed);ui(()->{check(a.settingsNavigation.prompt!=null,"Android Back also protects draft");a.settingsNavigation.prompt.getButton(AlertDialog.BUTTON_NEUTRAL).performClick();});ui(()->{check(draft.closed&&a.settingsSection.isEmpty(),"Discard returns Settings home");check(GlassAppearance.read(a).tint==originalTint,"Discard never saves tint");});
  open("Appearance");ready();ui(()->a.appearanceEditor.change(1,25));Thread.sleep(80);ui(()->{new DashSettings(a).open("Panel");a.settingsNavigation.prompt.getButton(AlertDialog.BUTTON_POSITIVE).performClick();});ui(()->{check("Panel".equals(a.settingsSection),"Save navigates to requested category");check(prefs.getInt("glass_transparency",20)==25,"Save commits draft before leaving");check(a.nativePanel==null&&a.webPanel==null&&a.fmPanel==null,"Settings does not start panel services");});
  AppearanceChecks.restore(prefs,before);ui(()->prefs.edit().putInt("dock_size",0).apply());open("Home & Dock");ui(()->{((Switch)find(a.stage,"Setting calendar")).setChecked(false);((Switch)find(a.stage,"Setting 24h")).setChecked(false);check(!prefs.getBoolean("calendar",true)&&!prefs.getBoolean("24h",true),"Home toggles save supported values");prefs.edit().putBoolean("calendar",true).putBoolean("24h",true).apply();View dock=find(a.stage,"Settings: Dock size");dock.performClick();a.settingsScreen.dialog.getListView().performItemClick(null,1,1);check(prefs.getInt("dock_size",0)==1,"existing Comfort dock profile saves");});ui(()->prefs.edit().putInt("dock_size",0).apply());open("Home & Dock");
  ui(()->{SettingsActions actions=a.settingsScreen.actions;String key="favorite_"+a.slots[0],old=prefs.getString(key,"");LauncherActivity.App missing=new LauncherActivity.App("Missing","dev.idash.notinstalled/.Main",null);check(!actions.select(0,missing),"uninstalled app cannot be saved");check(old.equals(prefs.getString(key,"")),"failed app selection retains previous choice");prefs.edit().putString(key,missing.component).apply();check(actions.favorite(0).contains("tiada"),"removed saved app has an explicit fallback");LauncherActivity.App valid=null;for(LauncherActivity.App app:a.apps)if(actions.installed(app.component)){valid=app;break;}check(valid!=null&&actions.select(0,valid),"installed app is accepted");});
  open("Home & Dock");capture("home-dock");open("Prayer Times");ui(()->a.setJakimZone("SGR02"));Thread.sleep(500);ui(()->{((Switch)find(a.stage,"Setting prayer_countdown")).setChecked(false);check(!prefs.getBoolean("prayer_countdown",true),"countdown saves using existing key");((Switch)find(a.stage,"Setting prayer_countdown")).setChecked(true);});long until=SystemClock.elapsedRealtime()+30000;while((a.settingsScreen.prayerStatus==null||!a.settingsScreen.prayerStatus.getText().toString().contains("hari dalam"))&&SystemClock.elapsedRealtime()<until)Thread.sleep(100);ui(()->{check(a.settingsScreen.prayerStatus.getText().toString().contains("365 hari"),"official bundled JAKIM coverage shown");check(a.settingsScreen.prayerStatus.getText().toString().contains("JAKIM"),"data source is explicit");});capture("waktu-solat");
  open("Panel");ui(()->{View mode=find(a.stage,"Settings: Default panel mode");mode.performClick();a.settingsScreen.dialog.getListView().performItemClick(null,2,2);check(prefs.getInt("panel_mode",0)==2,"Panel mode saves without starting it");check(a.carPanel==null&&a.nativePanel==null,"selecting Panel mode creates no renderer");});open("Panel");capture("panel");
  open("About");ui(()->{TextView version=(TextView)find(a.stage,"iDash version");check(version.getText().toString().contains("Build "+BuildConfig.VERSION_CODE),"version comes from actual build");find(a.stage,"Settings: Reset Settings").performClick();check(a.settingsScreen.dialog!=null,"reset always asks for confirmation");a.settingsScreen.dialog.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();check(prefs.contains("panel_mode"),"Cancel reset retains preferences");a.settingsScreen.actions.permissions();a.settingsScreen.dialog.getListView().performItemClick(null,3,3);check(a.settingsScreen.dialog.getButton(AlertDialog.BUTTON_POSITIVE)!=null,"DND access explanation has official Settings link");a.settingsScreen.dialog.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();});capture("about");
  open("Appearance");ready();capture("appearance");ui(()->a.appearanceEditor.cancel());ui(()->{check(a.settingsSection.isEmpty()&&"settings".equals(a.page),"Appearance Cancel returns Settings home");a.onBackPressed();check("home".equals(a.page),"Back from Settings keeps launcher open");});
  result.putString("stream","PASS: "+count+" complete Settings/navigation/action checks\n");code=Activity.RESULT_OK;
 }catch(Throwable failure){try{Bitmap screen=getUiAutomation().takeScreenshot();if(screen!=null){try(OutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),"settings-failure.png"))){screen.compress(Bitmap.CompressFormat.PNG,100,out);}screen.recycle();}}catch(Exception ignored){}result.putString("stream","FAIL after "+count+": "+failure+"\n");}finally{if(prefs!=null&&before!=null)AppearanceChecks.restore(prefs,before);if(a!=null)ui(()->{if(a.appearanceEditor!=null)a.appearanceEditor.close();if(a.settingsNavigation!=null)a.settingsNavigation.close();a.finish();});}finish(code,result);}
}
